import { useState, type ReactNode } from 'react'

import { useNavigate } from 'react-router-dom'

import { createTrainingPlan, findOverlappingFmPlans, isUniqueViolation } from '@/api/trainingPlans'
import { useAuth } from '@/contexts/AuthContext'
import { routes } from '@/routes'

import {
  PlanForm,
  PlanPathOverlapMessage,
  formDataToPlanInsert,
  type PlanFormData,
} from '../components'

export function PlansNewPage() {
  const navigate = useNavigate()
  const { user } = useAuth()
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<ReactNode | null>(null)

  async function handleSubmit(data: PlanFormData) {
    if (!data.name.trim()) {
      setError('계획 이름을 입력해주세요.')
      return
    }
    if (!data.unitName.trim()) {
      setError('훈련 단위를 입력해주세요.')
      return
    }
    if (data.scheduleType === 'weekly' && data.scheduleDays.length === 0) {
      setError('훈련 요일을 선택해주세요.')
      return
    }

    try {
      setLoading(true)
      setError(null)

      // 한 fm:// 폴더에 플랜 하나. DB 제약(018)에 걸리기 전에 안내한다.
      const [overlapping] = await findOverlappingFmPlans(user!.id, data.unitName)
      if (overlapping) {
        setError(<PlanPathOverlapMessage plan={overlapping} />)
        return
      }

      await createTrainingPlan(formDataToPlanInsert(data, user!.id))
      navigate(routes.plans.$())
    } catch (err) {
      // 사전 검사와 INSERT 사이의 경합, 또는 검사 조회 실패 시 DB 제약이 잡아준다.
      setError(
        isUniqueViolation(err)
          ? '같은 폴더를 가리키는 계획이 이미 있습니다. 기존 계획을 재사용해 주세요.'
          : '계획 생성에 실패했습니다.'
      )
      // eslint-disable-next-line no-console
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  function handleCancel() {
    navigate(routes.plans.$())
  }

  return (
    <PlanForm
      onSubmit={handleSubmit}
      onCancel={handleCancel}
      loading={loading}
      error={error}
      title="새 훈련 계획"
      submitLabel="계획 생성"
      loadingLabel="생성 중..."
    />
  )
}
